import importlib
import unittest


class FastAPIAppTest(unittest.TestCase):
    def setUp(self) -> None:
        try:
            importlib.import_module("fastapi")
        except ModuleNotFoundError as error:
            self.skipTest(f"FastAPI dependency is not installed: {error}")

    def test_app_imports_and_exposes_health_route(self) -> None:
        module = importlib.import_module("container.app")

        routes = {route.path for route in module.app.routes}
        self.assertIn("/health", routes)

    def test_playwright_server_options_omit_absent_proxy(self) -> None:
        module = importlib.import_module("container.main")

        options = module.build_playwright_server_options()

        self.assertNotIn("proxy", options)


if __name__ == "__main__":
    unittest.main()

import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    environment: "node",
    globals: true,
  },
});

import { beforeEach, describe, expect, it, vi } from "vitest";

const fetchCalls: Array<{ name: string; request: Request }> = [];

const getContainer = vi.fn((_binding: unknown, name?: string) => ({
  fetch: async (request: Request) => {
    fetchCalls.push({ name: name ?? "cf-singleton-container", request });
    return new Response(
      JSON.stringify({
        ok: true,
        url: request.url,
        port: request.headers.get("x-test-container-port"),
      }),
      { headers: { "content-type": "application/json" } },
    );
  },
}));

const getRandom = vi.fn(async (_binding: unknown, instances?: number) => ({
  fetch: async (request: Request) => {
    fetchCalls.push({ name: `random-${instances ?? "default"}`, request });
    return new Response(
      JSON.stringify({
        ok: true,
        url: request.url,
        port: request.headers.get("x-test-container-port"),
      }),
      { headers: { "content-type": "application/json" } },
    );
  },
}));

const switchPort = vi.fn((request: Request, port: number) => {
  const headers = new Headers(request.headers);
  headers.set("x-test-container-port", String(port));
  return new Request(request, { headers });
});

vi.mock("@cloudflare/containers", () => ({
  Container: class {},
  getContainer,
  getRandom,
  switchPort,
}));

const importWorker = async () => import("../src/index");

const makeEnv = (overrides: Record<string, unknown> = {}) =>
  ({
    CAMOUFOX: {},
    ...overrides,
  }) as never;

describe("worker routes", () => {
  beforeEach(() => {
    fetchCalls.length = 0;
    getContainer.mockClear();
    getRandom.mockClear();
    switchPort.mockClear();
  });

  it("returns endpoint metadata from the root route", async () => {
    const worker = await importWorker();

    const response = await worker.default.fetch(
      new Request("https://camoufox.example/"),
      makeEnv(),
    );

    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toMatchObject({
      service: "cloudflare-camoufox",
      endpoints: {
        playwright: "/playwright",
        content: "/content?url=https://example.com",
      },
    });
  });

  it("rejects content requests without a valid http url", async () => {
    const worker = await importWorker();

    const missing = await worker.default.fetch(
      new Request("https://camoufox.example/content"),
      makeEnv(),
    );
    const invalid = await worker.default.fetch(
      new Request("https://camoufox.example/content?url=file:///etc/passwd"),
      makeEnv(),
    );

    expect(missing.status).toBe(400);
    expect(invalid.status).toBe(400);
    expect(fetchCalls).toHaveLength(0);
  });

  it("proxies valid content requests to the default HTTP container port", async () => {
    const worker = await importWorker();

    const response = await worker.default.fetch(
      new Request(
        "https://camoufox.example/content?url=https%3A%2F%2Fexample.com",
      ),
      makeEnv(),
    );

    expect(response.status).toBe(200);
    expect(getContainer).toHaveBeenCalledWith({}, "browser");
    expect(fetchCalls).toHaveLength(1);
    expect(fetchCalls[0].request.url).toBe(
      "https://camoufox.example/content?url=https%3A%2F%2Fexample.com",
    );
    expect(switchPort).not.toHaveBeenCalled();
  });

  it("load balances content requests across configured container instances", async () => {
    const worker = await importWorker();

    const response = await worker.default.fetch(
      new Request(
        "https://camoufox.example/content?url=https%3A%2F%2Fexample.com",
      ),
      makeEnv({ CONTAINER_INSTANCE_COUNT: "10" }),
    );

    expect(response.status).toBe(200);
    expect(getRandom).toHaveBeenCalledWith({}, 10);
    expect(getContainer).not.toHaveBeenCalled();
    expect(fetchCalls).toHaveLength(1);
    expect(fetchCalls[0].name).toBe("random-10");
  });

  it("retries content requests once when a container has not finished starting", async () => {
    const worker = await importWorker();
    let attempts = 0;
    const originalGetRandom = getRandom.getMockImplementation();

    if (!originalGetRandom) {
      throw new Error("Missing getRandom mock implementation");
    }

    getRandom.mockImplementation(async (_binding: unknown, instances?: number) => ({
      fetch: async (request: Request) => {
        attempts += 1;
        if (attempts === 1) {
          return new Response("Failed to start container: The container is not running, consider calling start()", {
            status: 500,
          });
        }

        fetchCalls.push({ name: `retry-${instances ?? "default"}`, request });
        return new Response(
          JSON.stringify({
            ok: true,
            url: request.url,
            port: request.headers.get("x-test-container-port"),
          }),
          { headers: { "content-type": "application/json" } },
        );
      },
    }));

    let response: Response;
    try {
      response = await worker.default.fetch(
        new Request(
          "https://camoufox.example/content?url=https%3A%2F%2Fexample.com",
        ),
        makeEnv({ CONTAINER_INSTANCE_COUNT: "10" }),
      );
    } finally {
      getRandom.mockImplementation(originalGetRandom);
    }

    expect(response.status).toBe(200);
    expect(getRandom).toHaveBeenCalledTimes(2);
    expect(fetchCalls).toHaveLength(1);
    expect(fetchCalls[0].name).toBe("retry-10");
  });

  it("requires websocket upgrade for the Playwright route", async () => {
    const worker = await importWorker();

    const response = await worker.default.fetch(
      new Request("https://camoufox.example/playwright"),
      makeEnv(),
    );

    expect(response.status).toBe(426);
    expect(fetchCalls).toHaveLength(0);
  });

  it("proxies Playwright websocket requests to the Camoufox server port", async () => {
    const worker = await importWorker();

    const response = await worker.default.fetch(
      new Request("https://camoufox.example/playwright", {
        headers: { upgrade: "websocket" },
      }),
      makeEnv(),
    );

    expect(response.status).toBe(200);
    expect(getContainer).toHaveBeenCalledWith({}, "browser");
    expect(switchPort).toHaveBeenCalledWith(expect.any(Request), 9222);
    expect(fetchCalls).toHaveLength(1);
    expect(fetchCalls[0].request.headers.get("x-test-container-port")).toBe(
      "9222",
    );
  });

  it("load balances Playwright websocket requests across configured container instances", async () => {
    const worker = await importWorker();

    const response = await worker.default.fetch(
      new Request("https://camoufox.example/playwright", {
        headers: { upgrade: "websocket" },
      }),
      makeEnv({ CONTAINER_INSTANCE_COUNT: "10" }),
    );

    expect(response.status).toBe(200);
    expect(getRandom).toHaveBeenCalledWith({}, 10);
    expect(getContainer).not.toHaveBeenCalled();
    expect(switchPort).toHaveBeenCalledWith(expect.any(Request), 9222);
    expect(fetchCalls).toHaveLength(1);
    expect(fetchCalls[0].name).toBe("random-10");
    expect(fetchCalls[0].request.headers.get("x-test-container-port")).toBe(
      "9222",
    );
  });

  it("uses optional bearer authentication when API_TOKEN is configured", async () => {
    const worker = await importWorker();

    const unauthorized = await worker.default.fetch(
      new Request(
        "https://camoufox.example/content?url=https%3A%2F%2Fexample.com",
      ),
      makeEnv({ API_TOKEN: "secret" }),
    );
    const authorized = await worker.default.fetch(
      new Request(
        "https://camoufox.example/content?url=https%3A%2F%2Fexample.com",
        { headers: { authorization: "Bearer secret" } },
      ),
      makeEnv({ API_TOKEN: "secret" }),
    );

    expect(unauthorized.status).toBe(401);
    expect(authorized.status).toBe(200);
  });
});

from urllib.parse import urlparse


def normalize_http_url(value: str) -> str:
    target = value.strip()
    parsed = urlparse(target)

    if parsed.scheme not in {"http", "https"}:
        raise ValueError("url must use http or https")

    if not parsed.netloc:
        raise ValueError("url must include a host")

    return target

import {
  Container,
  getContainer,
  getRandom,
  switchPort,
} from "@cloudflare/containers";

const SERVICE_NAME = "cloudflare-camoufox";
const DEFAULT_CONTAINER_NAME = "browser";
const CAMOUFOX_HTTP_PORT = 8080;
const CAMOUFOX_PLAYWRIGHT_PORT = 9222;

export interface Env {
  CAMOUFOX: DurableObjectNamespace<CamoufoxContainer>;
  API_TOKEN?: string;
  CONTAINER_INSTANCE_COUNT?: string;
  CONTAINER_INSTANCE_NAME?: string;
}

export class CamoufoxContainer extends Container<Env> {
  defaultPort = CAMOUFOX_HTTP_PORT;
  requiredPorts = [CAMOUFOX_HTTP_PORT, CAMOUFOX_PLAYWRIGHT_PORT];
  sleepAfter = "10m";
  enableInternet = true;
  pingEndpoint = "container/health";
}

const json = (data: unknown, init: ResponseInit = {}) =>
  Response.json(data, {
    ...init,
    headers: {
      "content-type": "application/json; charset=utf-8",
      ...init.headers,
    },
  });

const isWebSocketUpgrade = (request: Request) =>
  request.headers.get("upgrade")?.toLowerCase() === "websocket";

const isAuthorized = (request: Request, env: Env) => {
  if (!env.API_TOKEN) {
    return true;
  }

  return request.headers.get("authorization") === `Bearer ${env.API_TOKEN}`;
};

const parseTargetUrl = (requestUrl: URL): string | null => {
  const value = requestUrl.searchParams.get("url");
  if (!value) {
    return null;
  }

  try {
    const target = new URL(value);
    if (target.protocol !== "http:" && target.protocol !== "https:") {
      return null;
    }

    if (!target.hostname) {
      return null;
    }

    return target.toString();
  } catch {
    return null;
  }
};

const getContainerInstanceCount = (env: Env) => {
  const count = Number.parseInt(env.CONTAINER_INSTANCE_COUNT ?? "1", 10);
  return Number.isFinite(count) && count > 1 ? count : 1;
};

const getBrowserContainer = async (env: Env) => {
  const instanceCount = getContainerInstanceCount(env);

  if (instanceCount > 1) {
    return getRandom(env.CAMOUFOX, instanceCount);
  }

  return getContainer(
    env.CAMOUFOX,
    env.CONTAINER_INSTANCE_NAME ?? DEFAULT_CONTAINER_NAME,
  );
};

const shouldRetryContainerResponse = async (response: Response) => {
  if (response.status !== 500 && response.status !== 503) {
    return false;
  }

  const body = await response.clone().text();
  return (
    body.startsWith("Failed to start container:") ||
    body.startsWith("There is no Container instance available")
  );
};

const proxyToBrowserContainer = async (
  env: Env,
  request: Request,
  port?: number,
) => {
  const instanceCount = getContainerInstanceCount(env);
  const maxAttempts = instanceCount > 1 ? 2 : 1;
  let response: Response | undefined;

  for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
    const container = await getBrowserContainer(env);
    response =
      port === undefined
        ? await container.fetch(request)
        : await container.fetch(switchPort(request, port));

    if (attempt < maxAttempts - 1 && (await shouldRetryContainerResponse(response))) {
      continue;
    }

    return response;
  }

  return response ?? new Response("Internal Server Error", { status: 500 });
};

export const handleRequest = async (request: Request, env: Env) => {
  const url = new URL(request.url);

  if (url.pathname === "/" || url.pathname === "/health") {
    return json({
      service: SERVICE_NAME,
      endpoints: {
        playwright: "/playwright",
        content: "/content?url=https://example.com",
      },
    });
  }

  if (!isAuthorized(request, env)) {
    return json({ error: "Unauthorized" }, { status: 401 });
  }

  if (url.pathname === "/content") {
    if (request.method !== "GET") {
      return json({ error: "Method Not Allowed" }, { status: 405 });
    }

    const targetUrl = parseTargetUrl(url);
    if (!targetUrl) {
      return json(
        { error: "The url query parameter must be an absolute http or https URL." },
        { status: 400 },
      );
    }

    return proxyToBrowserContainer(env, request);
  }

  if (url.pathname === "/playwright") {
    if (request.method !== "GET") {
      return json({ error: "Method Not Allowed" }, { status: 405 });
    }

    if (!isWebSocketUpgrade(request)) {
      return json(
        {
          error: "Expected a WebSocket upgrade request.",
          example: "await firefox.connect('wss://<worker-host>/playwright')",
        },
        {
          status: 426,
          headers: { upgrade: "websocket" },
        },
      );
    }

    return proxyToBrowserContainer(env, request, CAMOUFOX_PLAYWRIGHT_PORT);
  }

  return json({ error: "Not Found" }, { status: 404 });
};

export default {
  fetch: handleRequest,
} satisfies ExportedHandler<Env>;
